 1	// Sign-in for publishers and admins: Better Auth with GitHub as the only provider, stored in the same D1 database.
 2	// Better Auth owns the user, session, account and verification tables (schema.sql). The session cookie is host-only
 3	// (no Domain attribute), so it is sent to packs.maester.cloud alone and never to the rest of maester.cloud.
 4	import { betterAuth } from 'better-auth';
 5	import type { Env } from './index';
 6	
 7	export type Auth = ReturnType<typeof createAuth>;
 8	
 9	export function createAuth(env: Env, request: Request) {
10	  const origin = new URL(request.url).origin;
11	  return betterAuth({
12	    appName: 'Maester Packs',
13	    baseURL: env.SITE_URL || origin,
14	    basePath: '/api/auth',
15	    secret: env.BETTER_AUTH_SECRET,
16	    database: env.DB,
17	    trustedOrigins: [env.SITE_URL || origin],
18	    telemetry: { enabled: false },
19	    socialProviders: {
20	      github: {
21	        clientId: env.GITHUB_CLIENT_ID,
22	        clientSecret: env.GITHUB_CLIENT_SECRET,
23	        // Added to Better Auth's read:user and user:email: read:org lists the organisations a publisher belongs to, so they
24	        // can publish an organisation's repository.
25	        scope: ['read:org'],
26	        mapProfileToUser: (profile) => ({ githubLogin: profile.login }),
27	      },
28	    },
29	    user: {
30	      additionalFields: {
31	        githubLogin: { type: 'string', required: false, input: false },
32	      },
33	    },
34	    account: {
35	      encryptOAuthTokens: true,
36	    },
37	    session: {
38	      expiresIn: 60 * 60 * 24 * 14,
39	      updateAge: 60 * 60 * 24,
40	    },
41	    advanced: {
42	      cookiePrefix: 'packs',
43	      useSecureCookies: origin.startsWith('https://'),
44	      defaultCookieAttributes: { sameSite: 'lax', httpOnly: true, path: '/' },
45	    },
46	  });
47	}
48	
49	export interface Viewer {
50	  userId: string;
51	  githubId: number;
52	  login: string;
53	  name: string;
54	  image: string | null;
55	  admin: boolean;
56	  accountRowId: string;
57	}
58	
59	// The signed-in person, with their GitHub ID and whether they are an admin, or null. Admins are the GitHub IDs in
60	// ADMIN_GITHUB_IDS (merill by default) plus anyone an admin added on the admin page.
61	export async function getViewer(auth: Auth, env: Env, request: Request): Promise<Viewer | null> {
62	  const session = await auth.api.getSession({ headers: request.headers });
63	  if (!session) return null;
64	  const row = await env.DB.prepare(`SELECT id, accountId FROM account WHERE userId = ? AND providerId = 'github' LIMIT 1`)
65	    .bind(session.user.id).first<{ id: string; accountId: string }>();
66	  if (!row) return null;
67	  const githubId = Number(row.accountId);
68	  const user = session.user as typeof session.user & { githubLogin?: string | null };
69	  return {
70	    userId: session.user.id,
71	    githubId,
72	    login: user.githubLogin || session.user.name,
73	    name: session.user.name,
74	    image: session.user.image ?? null,
75	    admin: await isAdmin(env, githubId),
76	    accountRowId: row.id,
77	  };
78	}
79	
80	export function bootstrapAdmins(env: Env): number[] {
81	  return (env.ADMIN_GITHUB_IDS || '').split(',').map((s) => Number(s.trim())).filter((n) => Number.isInteger(n) && n > 0);
82	}
83	
84	export async function isAdmin(env: Env, githubId: number): Promise<boolean> {
85	  if (bootstrapAdmins(env).includes(githubId)) return true;
86	  const row = await env.DB.prepare('SELECT 1 AS ok FROM site_admins WHERE github_id = ?').bind(githubId).first();
87	  return !!row;
88	}
89	
90	// The publisher's GitHub token, refreshed by Better Auth when needed. It never leaves the Worker.
91	export async function githubToken(auth: Auth, viewer: Viewer, request: Request): Promise<string | null> {
92	  try {
93	    const result = await auth.api.getAccessToken({ body: { accountId: viewer.accountRowId }, headers: request.headers });
94	    return result?.accessToken ?? null;
95	  } catch {
96	    return null;
97	  }
98	}

