1	// The signed-in parts of packs.maester.cloud: a publisher verifying and publishing their own repositories, and what
2	// admins manage (reserved codes, the blocklist, official and featured packs, the pack registry, other admins). The
3	// index reads all of it from /api/v1/site-data with its read-only key, so the site is its only source of truth.
4	//
5	// Every write needs a session and an Origin header from this site; the session cookie is SameSite=Lax, so a request
6	// from another site carries no session anyway.
7	//
8	// The pack registry binds each pack's Guid to its code and to the GitHub owner that published it. Publishing is the
9	// only way in: a signed-in admin of the public repository presses Publish, and the Worker checks the Guid and code.
10	// A Guid keeps its code for good, and a code stays taken even if its repository goes private, so a publisher cannot
11	// take over someone else's code by copying their manifest. Codes outside this site are the publisher's business:
12	// private packs can use any code, and Maester tells packs apart by Guid.
13	import { createAuth, getViewer, githubToken, bootstrapAdmins, type Viewer, type Auth } from './auth';
14	import type { Env } from './index';
15	import { json, packKey, timingSafeEqual } from './util';
16	
17	const CODE = /^[A-Z][A-Z0-9]{1,9}(\.[A-Z][A-Z0-9]{1,9}){0,2}$/;
18	const VERSION = /^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/;
19	const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
20	const MAX_TEXT = 500;
21	const MINIMUM_OWNER_AGE_DAYS = 30;
22	const RESERVED_INFO = 'The Maester maintainers keep some codes back, such as names that look official or belong to a product\'s vendor, so nobody can publish a pack that looks like theirs. A reserved code can be assigned to the organisation it belongs to: if it is yours, ask in a pack-report issue in maester365/maester.';
23	
24	type ListName = 'reserved' | 'blocklist' | 'official' | 'featured';
25	const LISTS: ListName[] = ['reserved', 'blocklist', 'official', 'featured'];
26	// The packs their publishers have taken off the site for now, keyed by Guid. Publishers set it, not admins.
27	// 'unlisted' is the moderators' counterpart: a pack an admin took off the site at one commit, with the reason, until
28	// the publisher releases a new commit.
29	type StoredList = ListName | 'hidden' | 'unlisted';
30	
31	export async function handleSite(request: Request, env: Env, url: URL): Promise<Response | null> {
32	  const path = url.pathname;
33	  githubApi = env.GITHUB_API_URL || 'https://api.github.com';
34	  if (path === '/api/v1/codes' && request.method === 'GET') return getCodes(env);
35	  if (path === '/api/v1/site-data' && request.method === 'GET') return getSiteData(request, env);
36	  if (!path.startsWith('/api/v1/me') && !path.startsWith('/api/v1/admin')) return null;
37	
38	  if (request.method !== 'GET' && !sameOrigin(request, env)) return json({ error: 'Cross-site request refused' }, 403);
39	  const auth = createAuth(env, request);
40	  const viewer = await getViewer(auth, env, request);
41	  if (path === '/api/v1/me' && request.method === 'GET') {
42	    return json(viewer ? { signedIn: true, login: viewer.login, name: viewer.name, image: viewer.image, githubId: viewer.githubId, admin: viewer.admin } : { signedIn: false }, 200, { 'Cache-Control': 'no-store' });
43	  }
44	  if (!viewer) return json({ error: 'Sign in with GitHub first' }, 401);
45	
46	  if (path === '/api/v1/me/repos' && request.method === 'GET') return listRepos(auth, env, viewer, request);
47	  if (path === '/api/v1/me/check' && request.method === 'POST') return checkOrPublish(auth, env, viewer, request, false);
48	  if (path === '/api/v1/me/publish' && request.method === 'POST') return checkOrPublish(auth, env, viewer, request, true);
49	  if (path === '/api/v1/me/packs' && request.method === 'GET') return myPacks(env, viewer, auth, request);
50	  if (path === '/api/v1/me/packs/hidden' && request.method === 'POST') return setHidden(auth, env, viewer, request);
51	
52	  if (path.startsWith('/api/v1/admin')) {
53	    if (!viewer.admin) return json({ error: 'Admins only' }, 403);
54	    if (path === '/api/v1/admin/admins') {
55	      if (request.method === 'GET') return listAdmins(env);
56	      if (request.method === 'POST') return addAdmin(auth, env, viewer, request);
57	      if (request.method === 'DELETE') return removeAdmin(env, viewer, url);
58	    }
59	    if (path === '/api/v1/admin/unlisted') {
60	      if (request.method === 'GET') return json({ items: await readList(env, 'unlisted') }, 200, { 'Cache-Control': 'no-store' });
61	      if (request.method === 'POST') return unlist(env, viewer, request);
62	      if (request.method === 'DELETE') return relist(env, viewer, url);
63	    }
64	    if (path === '/api/v1/admin/registry') {
65	      if (request.method === 'GET') return json({ items: await registry(env) }, 200, { 'Cache-Control': 'no-store' });
66	      if (request.method === 'DELETE') return removeRegistration(env, viewer, url);
67	    }
68	    const list = path.slice('/api/v1/admin/'.length) as ListName;
69	    if (LISTS.includes(list)) {
70	      if (request.method === 'GET') return json({ items: await readList(env, list) }, 200, { 'Cache-Control': 'no-store' });
71	      if (request.method === 'POST') return upsertListItem(env, viewer, list, request);
72	      if (request.method === 'DELETE') return deleteListItem(env, viewer, list, url);
73	    }
74	  }
75	  return json({ error: 'Not found' }, 404);
76	}
77	
78	function sameOrigin(request: Request, env: Env): boolean {
79	  const origin = request.headers.get('Origin');
80	  const expected = env.SITE_URL || new URL(request.url).origin;
81	  return !!origin && origin === expected;
82	}
83	
84	async function readBody(request: Request): Promise<Record<string, unknown> | null> {
85	  if (!(request.headers.get('Content-Type') ?? '').startsWith('application/json')) return null;
86	  const text = await request.text();
87	  if (text.length > 8192) return null;
88	  try {
89	    const body = JSON.parse(text);
90	    return body && typeof body === 'object' && !Array.isArray(body) ? body : null;
91	  } catch {
92	    return null;
93	  }
94	}
95	
96	function text(value: unknown, max = MAX_TEXT): string {
97	  return typeof value === 'string' ? value.replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max) : '';
98	}
99	
100	async function log(env: Env, viewer: Viewer, action: string, detail: unknown): Promise<void> {
101	  await env.DB.prepare('INSERT INTO admin_log (at, github_id, login, action, detail) VALUES (?, ?, ?, ?, ?)')
102	    .bind(new Date().toISOString(), viewer.githubId, viewer.login, action, JSON.stringify(detail).slice(0, 2000)).run();
103	}
104	
105	// ---- GitHub, as the signed-in publisher ----------------------------------------------------------------------
106	
107	let githubApi = 'https://api.github.com';
108	
109	async function gh<T>(token: string, path: string): Promise<{ status: number; body: T | null }> {
110	  const response = await fetch(`${githubApi}/${path}`, {
111	    headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'User-Agent': 'packs.maester.cloud', 'X-GitHub-Api-Version': '2022-11-28' },
112	  });
113	  if (!response.ok) return { status: response.status, body: null };
114	  return { status: response.status, body: (await response.json()) as T };
115	}
116	
117	interface GhRepo {
118	  id: number; name: string; full_name: string; private: boolean; visibility?: string; fork: boolean; archived: boolean;
119	  description: string | null; pushed_at: string; owner: { login: string; id: number; type: string };
120	  permissions?: { admin?: boolean };
121	}
122	
123	// The public repositories the publisher administers, their own and their organisations'. Only these can be published:
124	// a private or internal repository is never listed, and neither is one the publisher cannot administer.
125	async function listRepos(auth: Auth, env: Env, viewer: Viewer, request: Request): Promise<Response> {
126	  const token = await githubToken(auth, viewer, request);
127	  if (!token) return json({ error: 'GitHub did not give us a token. Sign out and sign in again.' }, 401);
128	  const repos: GhRepo[] = [];
129	  for (let page = 1; page <= 5; page++) {
